import { execFileSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { PIECE_TYPES } from '../rules/pieces';

// The piece art sprite (src/assets/pieces.svg) is generated by scripts/make-pieces.mjs.
const sprite = readFileSync('src/assets/pieces.svg', 'utf8');

describe('piece art', () => {
  it('has a drawing for every piece type', () => {
    for (const type of PIECE_TYPES) expect(sprite, `no art for ${type}`).toContain(`<symbol id="piece-${type}"`);
  });

  it('is coloured only by the CSS variables, so any piece can be drawn in any colours', () => {
    const colours = sprite.match(/(?:fill|stroke)="[^"]*"/g) ?? [];
    for (const c of colours) expect(c).toMatch(/="(none|var\(--piece-[a-z]+.*\))"$/);
  });

  it('matches its drawings (run node scripts/make-pieces.mjs after changing them)', () => {
    execFileSync('node', ['scripts/make-pieces.mjs']);
    expect(readFileSync('src/assets/pieces.svg', 'utf8')).toBe(sprite);
  });
});
